/**
 * Sprint aux — typed views for the S25–S88 sniper / Phase 6 simulation schemas.
 *
 * The fixtures under ../fixtures/sample-{simulation,sniper,phase6}-*.json are
 * FICTIONAL artifacts generated by the BACKEND PRODUCTION BUILDERS (the same
 * fictional fixture chain the repo's e2e tests use — fictional mints, sample
 * labels, nothing live, no real market data, no real wallet anywhere).
 *
 * Proves, against those real shapes:
 *   - the registry recognizes every S25–S87 schema with its real CLI command;
 *   - typed views render honest state: route resolution UNAVAILABLE is the
 *     truthful capability boundary (not success, not failure), readiness shows
 *     the eleven-area evidence bar incl. route-resolution-tests, audit/handoff
 *     show the S87 route-resolution role;
 *   - SAMPLE labels stay visible; safety locks are echoed; an unsafe lock
 *     claim gets a loud tamper warning;
 *   - unknown schemas still degrade honestly (no typed view, no fake verdict);
 *   - hostile/missing-field shapes never throw and never inject;
 *   - no fake live/execution wording anywhere.
 */

import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";

import { renderToString } from "../src/lib/html.js";
import { normalizeArtifact } from "../src/lib/local-artifact.js";
import { knownSchema, isKnownSchema } from "../src/lib/report-types.js";
import { extractVerdict } from "../src/lib/folder-index.js";
import { hasTypedView, renderTypedArtifactView } from "../src/components/artifact-views.js";

function loadFixture(name: string): unknown {
  const path = fileURLToPath(new URL(`../fixtures/${name}`, import.meta.url));
  return JSON.parse(readFileSync(path, "utf8")) as unknown;
}

function typed(raw: unknown): string {
  const view = renderTypedArtifactView(normalizeArtifact(raw), raw);
  expect(view).not.toBeNull();
  return renderToString(view!);
}

/** Live/execution claims no paper/simulation view may ever make. */
const FORBIDDEN_PHRASES = [
  "trade executed",
  "trade placed",
  "transaction sent",
  "transaction signed",
  "order filled",
  "position opened",
  "ready for live",
  "live-ready",
  "live trading ready: yes",
  "safe with real funds",
  "guaranteed",
  "profitable",
];

const FIXTURES: ReadonlyArray<readonly [string, string]> = [
  ["sample-sniper-decision-v2.json", "sniper.paper.decision.report.v2"],
  ["sample-sniper-run-report-v2.json", "sniper.run.report.v2"],
  ["sample-sniper-run-report-diff-v2.json", "sniper.run.report.diff.v2"],
  ["sample-simulation-intent-plan.json", "simulation.intent.plan.v2"],
  ["sample-simulation-result.json", "simulation.result.v1"],
  ["sample-simulation-route-resolution.json", "simulation.route.resolution.v1"],
  ["sample-simulation-plan-diff.json", "simulation.intent.plan.diff.v2"],
  ["sample-simulation-result-diff.json", "simulation.result.diff.v1"],
  ["sample-phase6-audit-report.json", "phase6.audit.report.v1"],
  ["sample-phase6-readiness-report.json", "phase6.simulation.readiness.report.v1"],
  ["sample-phase6-handoff-pack.json", "phase6.simulation.handoff.pack.v1"],
  ["sample-phase6-operator-bundle.json", "phase6.operator.bundle.v1"],
];

describe("registry — every S25–S88 schema is catalogued with its real CLI", () => {
  const EXPECTED_CLI: Readonly<Record<string, string>> = {
    "sniper.paper.decision.report.v2": "paper:sniper:decide",
    "sniper.run.report.v2": "paper:sniper:report",
    "sniper.run.report.diff.v2": "paper:sniper:diff:report",
    "simulation.intent.plan.v2": "paper:simulation:intent:plan",
    "simulation.result.v1": "paper:simulation:result",
    "simulation.route.resolution.v1": "paper:simulation:route",
    "simulation.intent.plan.diff.v2": "paper:simulation:diff:plan",
    "simulation.result.diff.v1": "paper:simulation:diff:result",
    "phase6.audit.report.v1": "paper:simulation:audit",
    "phase6.simulation.readiness.report.v1": "paper:simulation:readiness",
    "phase6.simulation.handoff.pack.v1": "paper:simulation:handoff",
    "phase6.operator.bundle.v1": "paper:simulation:bundle",
  };

  for (const [id, cli] of Object.entries(EXPECTED_CLI)) {
    it(`recognizes ${id} (stable, CLI ${cli}, typed view shipped)`, () => {
      const info = knownSchema(id);
      expect(info).toBeDefined();
      expect(info?.stability).toBe("stable");
      expect(info?.cli).toBe(cli);
      expect(hasTypedView(id)).toBe(true);
    });
  }

  it("every fixture declares the schema this suite expects (no drift)", () => {
    for (const [file, schema] of FIXTURES) {
      const raw = loadFixture(file) as Record<string, unknown>;
      expect(raw.schemaVersion, file).toBe(schema);
    }
  });

  it("an unknown schema is still unknown (no over-claiming)", () => {
    expect(isKnownSchema("simulation.route.resolution.v9")).toBe(false);
    expect(hasTypedView("simulation.route.resolution.v9")).toBe(false);
  });
});

describe("route resolution — UNAVAILABLE renders as the truthful boundary", () => {
  const out = typed(loadFixture("sample-simulation-route-resolution.json"));

  it("renders UNAVAILABLE as a capability boundary, never as success or failure", () => {
    expect(out).toContain("Route resolution UNAVAILABLE — the truthful capability boundary, not a failure");
    expect(out).toContain("No route resolver exists inside the simulation boundary");
    expect(out).toContain("UNAVAILABLE");
  });

  it("shows the fixed no-resolver id and that no attempt was claimed", () => {
    expect(out).toContain("unavailable-no-route-resolver");
    // S91 wording: an unattempted resolution states plainly that nothing was attempted.
    expect(out).toContain("no — nothing was attempted; every fact stays honestly unresolved");
  });

  it("renders per-entry route/destination/fee facts as UNRESOLVED (never invented)", () => {
    expect(out).toContain("UNRESOLVED (never invented)");
  });

  it("echoes the safety locks including the always-false phase7LiveTradingReady", () => {
    expect(out).toContain("phase7LiveTradingReady");
    expect(out).toContain("can never claim live-trading readiness");
  });

  it("carries the artifact's own next safe action", () => {
    expect(out).toContain("Next safe action (from the artifact)");
  });
});

describe("readiness — the eleven-area evidence bar is visible", () => {
  const out = typed(loadFixture("sample-phase6-readiness-report.json"));

  it("shows the route-resolution-tests evidence area (the S86 eleventh area)", () => {
    expect(out).toContain("route-resolution-tests");
    expect(out).toContain("eleven-area evidence bar");
  });

  it("pins Phase 7 to a permanent NO in plain language", () => {
    expect(out).toContain("phase 7 live trading ready");
    expect(out).toContain("permanently; Phase 7 remains not started and unauthorized");
  });

  it("says evidence references are declarations, never verified here", () => {
    expect(out).toContain("verbatim; never verified here");
  });
});

describe("audit / handoff — the S87 route-resolution role is visible", () => {
  const audit = typed(loadFixture("sample-phase6-audit-report.json"));
  const handoff = typed(loadFixture("sample-phase6-handoff-pack.json"));

  it("the audit lists the route-resolution role among the audited roles", () => {
    expect(audit).toContain("route-resolution");
    expect(audit).toContain("including the route-resolution role added by Sprint 87");
    expect(audit).toContain("simulation.route.resolution.v1");
  });

  it("the audit leads with its verdict and never authorizes", () => {
    expect(audit).toContain("reports the chain — never authorizes anything");
    expect(audit).toContain("PASSED (no blocking finding)");
  });

  it("the handoff lists the route-resolution role with its verbatim summary", () => {
    expect(handoff).toContain("route-resolution");
    expect(handoff).toContain("including the route-resolution role added by Sprint 87");
    expect(handoff).toContain("resolutionStatus=unavailable");
  });

  it("the handoff carries the verbatim readiness verdict, never as live readiness", () => {
    expect(handoff).toContain("phase 6 SIMULATION ready (never live readiness)");
  });
});

describe("operator bundle — the S88 archive/review view stays honest", () => {
  const raw = loadFixture("sample-phase6-operator-bundle.json") as Record<string, unknown>;
  const out = typed(raw);

  it("leads with the closed-set operator verdict — honestly BLOCKED for the ready chain", () => {
    // The ready chain's paper-enters always demand operator review, so its bundle
    // is honestly blocked on the verbatim prereqs condition. Correct and expected.
    expect(out).toContain("Operator verdict: BLOCKED");
    expect(out).toContain("operator verdict");
  });

  it("carries the chain blocking codes verbatim (recomputed, never waived)", () => {
    expect(out).toContain("simulation-blocked-prereqs-not-ready");
    expect(out).toContain("Chain blocking conditions (recomputed — never waived)");
    expect(out).toContain("Handoff pack&#39;s verbatim trail");
  });

  it("shows the deterministic what-happened line and the why-blocked / inspect-next lists", () => {
    expect(out).toContain("What happened (deterministic, from the artifact)");
    expect(out).toContain("One PAPER dry-run chain collected: 13/13 artifacts strictly valid");
    expect(out).toContain("Why blocked (1; deterministic operator lines");
    expect(out).toContain("What to inspect next (from the artifact)");
    expect(out).toContain("re-run paper:simulation:audit");
  });

  it("lists all thirteen roles including the handoff pack itself, with file + digest refs", () => {
    expect(out).toContain("the twelve handoff roles plus the handoff pack itself (Sprint 88)");
    expect(out).toContain("handoff-pack");
    expect(out).toContain("decision.json");
    expect(out).toContain("sha256-128:");
  });

  it("reports the blocking trail CONSISTENT for the honestly-built fixture", () => {
    expect(out).toContain("CONSISTENT — the pack&#39;s verbatim codes equal the recomputed trail");
    expect(out).not.toContain("possible stale or TAMPERED handoff pack");
  });

  it("warns LOUDLY when the blocking trail reads inconsistent (stale/tampered pack)", () => {
    const tampered = typed({ ...raw, blockingTrailConsistent: false });
    expect(tampered).toContain("Blocking trail INCONSISTENT — possible stale or TAMPERED handoff pack");
    expect(tampered).toContain("was not built from THIS artifact set");
  });

  it("renders route resolution UNAVAILABLE as the honest boundary, never an error", () => {
    expect(out).toContain("UNAVAILABLE — the honest capability boundary (no route resolver exists)");
    expect(out).toContain("the expected Phase 6 state, not an error");
    expect(out).toContain("no resolver capability exists inside the boundary");
  });

  it("carries the verbatim readiness verdict, never phrased as live readiness", () => {
    expect(out).toContain("phase 6 SIMULATION ready (never live readiness)");
  });

  it("echoes the sample labels and the always-false phase7 lock", () => {
    expect(out).toContain("sample-fictional-bundle");
    expect(out).toContain("sample-fictional-operator");
    expect(out).toContain("phase7LiveTradingReady");
    expect(out).toContain("can never claim live-trading readiness");
  });

  it("a missing/null route or readiness reads as honestly unknown, never guessed", () => {
    const degraded = typed({
      schemaVersion: "phase6.operator.bundle.v1",
      operatorVerdict: "incomplete",
      routeResolutionStatus: null,
      simulationReadyPerReadiness: null,
      blockingTrailConsistent: null,
    });
    expect(degraded).toContain("Operator verdict: INCOMPLETE");
    expect(degraded).toContain("unknown — no valid route artifact bundled (never guessed)");
    expect(degraded).toContain("unknown — no valid readiness report supplied (never guessed)");
    expect(degraded).toContain("not fully recomputable");
    expect(degraded).toContain("Partial view");
  });

  it("an unrecognized verdict degrades honestly (never treated as reviewable)", () => {
    const weird = typed({ ...raw, operatorVerdict: "totally-ready-for-live" });
    expect(weird).toContain("Operator verdict missing or unrecognized");
    expect(weird).toContain("never as reviewable");
  });

  it("the BEST verdict is reviewable-paper-only and is still framed as simulation only", () => {
    const reviewable = typed({ ...raw, operatorVerdict: "reviewable-paper-only" });
    expect(reviewable).toContain("reviewable-paper-only — the BEST verdict this artifact can carry");
    expect(reviewable).toContain("SIMULATION ONLY");
    expect(reviewable.toLowerCase()).not.toContain("ready for live");
  });
});

