describe("honest degradation — tamper warnings, missing fields, hostile shapes", () => {
  it("a flipped safety lock gets a loud tamper warning", () => {
    const raw = loadFixture("sample-simulation-route-resolution.json") as Record<string, unknown>;
    const out = typed({ ...raw, neverSends: false });
    expect(out).toContain("Unsafe lock claim — treat this artifact as tampered");
    expect(out).toContain("neverSends");
  });

  it("a flipped phase7LiveTradingReady gets the same tamper warning", () => {
    const raw = loadFixture("sample-phase6-readiness-report.json") as Record<string, unknown>;
    const out = typed({ ...raw, phase7LiveTradingReady: true });
    expect(out).toContain("Unsafe lock claim — treat this artifact as tampered");
    expect(out).toContain("phase7LiveTradingReady");
  });

  it("minimal shapes (schemaVersion only) never throw and show a partial-view notice", () => {
    for (const [, schema] of FIXTURES) {
      const view = renderTypedArtifactView(
        normalizeArtifact({ schemaVersion: schema }),
        { schemaVersion: schema },
      );
      expect(view, schema).not.toBeNull();
      const out = renderToString(view!);
      expect(out, schema).toContain("Partial view");
    }
  });

  it("hostile type-mismatched shapes never throw", () => {
    for (const [, schema] of FIXTURES) {
      const hostile = {
        schemaVersion: schema,
        entries: "nope",
        artifacts: 42,
        evidence: { not: "an array" },
        base: "x",
        next: [],
        sourcePlanRef: 7,
        reasonCodeCounts: "no",
      };
      expect(() => typed(hostile), schema).not.toThrow();
    }
  });

  it("hostile string content is escaped, never injected", () => {
    const out = typed({
      schemaVersion: "simulation.intent.plan.v2",
      planLabel: "<script>alert(1)</script>",
      blocked: false,
      entryCount: 0,
    });
    expect(out).not.toContain("<script>alert");
    expect(out).toContain("&lt;script&gt;");
  });
});

describe("no fake live/execution wording in any rendered view", () => {
  for (const [file] of FIXTURES) {
    it(`${file} renders without forbidden live/execution claims`, () => {
      const lower = typed(loadFixture(file)).toLowerCase();
      for (const phrase of FORBIDDEN_PHRASES) {
        expect(lower, `"${phrase}" must never appear in ${file}`).not.toContain(phrase);
      }
    });
  }
});

describe("folder verdicts — the new diff schemas report their OWN flags only", () => {
  it("the plan diff reports change + regression from hasChange / hasNewBlocking", () => {
    const raw = loadFixture("sample-simulation-plan-diff.json");
    const verdict = extractVerdict("simulation.intent.plan.diff.v2", raw);
    // The sample diff compares a clean plan against a stop-tripped one.
    expect(verdict.hasChange).toBe("yes");
    expect(verdict.hasRegression).toBe("yes");
    expect(verdict.notes.join(" ")).toContain("hasNewBlocking");
  });

  it("the identical result self-diff reports no change and no regression", () => {
    const raw = loadFixture("sample-simulation-result-diff.json");
    const verdict = extractVerdict("simulation.result.diff.v1", raw);
    expect(verdict.hasChange).toBe("no");
    expect(verdict.hasRegression).toBe("no");
  });

  it("the run report diff v2 reads hasAnyChange / hasNewOperatorBlocking", () => {
    const raw = loadFixture("sample-sniper-run-report-diff-v2.json");
    const verdict = extractVerdict("sniper.run.report.diff.v2", raw);
    expect(verdict.hasChange).toBe("yes");
    expect(verdict.hasRegression).toBe("yes");
    expect(verdict.notes.join(" ")).toContain("hasAnyChange");
    expect(verdict.notes.join(" ")).toContain("hasNewOperatorBlocking");
  });

  it("non-diff Phase 6 artifacts carry no verdict (not-applicable, never inferred)", () => {
    for (const schema of [
      "simulation.intent.plan.v2",
      "simulation.result.v1",
      "simulation.route.resolution.v1",
      "phase6.audit.report.v1",
      "phase6.simulation.readiness.report.v1",
      "phase6.simulation.handoff.pack.v1",
      "phase6.operator.bundle.v1",
    ]) {
      const verdict = extractVerdict(schema, { hasChange: true, hasRegression: true });
      expect(verdict.hasChange, schema).toBe("not-applicable");
      expect(verdict.hasRegression, schema).toBe("not-applicable");
    }
  });

  it("the operator bundle's own blocked state never leaks into a diff verdict", () => {
    // The S88 bundle is a point-in-time artifact, not a base→next comparison.
    // Its operatorVerdict/hasBlockingConditions standing belongs to its typed
    // view; the folder diff-verdict overview reports it as not-applicable —
    // never a forced/fake regression flag.
    const raw = loadFixture("sample-phase6-operator-bundle.json");
    const verdict = extractVerdict("phase6.operator.bundle.v1", raw);
    expect(verdict.hasChange).toBe("not-applicable");
    expect(verdict.hasRegression).toBe("not-applicable");
    expect(verdict.notes.join(" ")).toContain("recognized non-diff artifact");
  });

  it("an unknown simulation-looking schema still gets no verdict (no fake precision)", () => {
    const verdict = extractVerdict("simulation.route.resolution.v9", { hasChange: true });
    expect(verdict.hasChange).toBe("not-applicable");
    expect(verdict.hasRegression).toBe("not-applicable");
  });
});
